public UserProfile fetchAggregatedUserData(String userId) throws InterruptedException, ExecutionException {
    try (var scope = new ShutdownOnFailure()) {
        Supplier<UserAccount> accountTask = scope.fork(() -> userService.getAccount(userId));
        Supplier<List<Order>> ordersTask = scope.fork(() -> orderService.getRecentOrders(userId));
        Supplier<Preferences> prefsTask = scope.fork(() -> preferenceService.getPrefs(userId));

        scope.join();          // Wait for all subtasks to complete or one to fail
        scope.throwIfFailed(); // Propagate exception if any subtask failed, triggering automatic shutdown

        return new UserProfile(accountTask.get(), ordersTask.get(), prefsTask.get());
    }
}
